<?php
$projectStmt=db()->prepare('SELECT id,titre,categorie,description FROM realisations WHERE id=:id AND actif=1');
$projectStmt->execute(['id'=>$realisationReviewId]);
$project=$projectStmt->fetch();
if (!$project) { http_response_code(404); echo '<section class="page-intro"><h1>Projet introuvable</h1><a href="?page=home">Retour à l’accueil</a></section>'; return; }
$summaryStmt=db()->prepare("SELECT AVG(note) AS average,COUNT(*) AS total FROM avis_terrains WHERE realisation_id=:id AND statut='publie'");
$summaryStmt->execute(['id'=>$project['id']]);
$summary=$summaryStmt->fetch();
$reviewsStmt=db()->prepare("SELECT nom,note,commentaire,date_creation FROM avis_terrains WHERE realisation_id=:id AND statut='publie' ORDER BY date_creation DESC LIMIT 20");
$reviewsStmt->execute(['id'=>$project['id']]);
$reviews=$reviewsStmt->fetchAll();
?>
<section class="page-intro review-intro"><span class="eyebrow"><?= e($project['categorie']) ?></span><h1><?= e($project['titre']) ?></h1><p><?= e($project['description']) ?></p><a class="back-link" href="?page=home#projects">← Retour aux projets</a></section>
<section class="reviews-section"><div class="reviews-heading"><div><span class="eyebrow">AVIS CLIENTS</span><h2>Expériences partagées</h2></div><?= star_rating((float)($summary['average'] ?? 0),(int)$summary['total']) ?></div><div class="review-columns"><div class="review-list"><?php if ($reviews): foreach ($reviews as $review): ?><article class="review-card"><div class="review-card-head"><strong><?= e($review['nom']) ?></strong><?= star_rating((float)$review['note']) ?></div><p><?= nl2br(e($review['commentaire'])) ?></p><time><?= e(date('d/m/Y',strtotime($review['date_creation']))) ?></time></article><?php endforeach; else: ?><p class="empty-reviews">Aucun avis publié pour cette réalisation.</p><?php endif; ?></div><form class="review-form glass-filter" method="post" action="?page=avis&amp;realisation=<?= (int)$project['id'] ?>"><?= csrf_field() ?><input type="hidden" name="action" value="submit_review"><input type="hidden" name="type_cible" value="realisation"><input type="hidden" name="realisation_id" value="<?= (int)$project['id'] ?>"><label class="honeypot" aria-hidden="true">Ne pas remplir<input name="website" tabindex="-1" autocomplete="off"></label><span class="eyebrow">VOTRE RETOUR</span><h2>Évaluer ce projet</h2><label>Votre nom<input name="nom" maxlength="120" required autocomplete="name"></label><fieldset class="star-picker"><legend>Votre note</legend><?php for ($star=5;$star>=1;$star--): ?><label><input type="radio" name="note" value="<?= $star ?>" required><span aria-label="<?= $star ?> sur 5">★</span></label><?php endfor; ?></fieldset><label>Votre avis<textarea name="commentaire" maxlength="2000" rows="5" required placeholder="Partagez votre expérience..."></textarea></label><button class="button button-green">Envoyer pour modération <span>↗</span></button><small>Votre avis sera visible après validation par l’équipe.</small></form></div></section>